import gzip
import shutil
from pathlib import Path
from zipfile import ZipFile


def extract_specific_file_from_zip(path_to_zip, filename_part, dest_dir=None):
    """
    Search for specific file in zip and extract it to the given directory.
    :param path_to_zip: path to a zip file
    :param filename_part: string with filename's part to find in Snapshot
    :param dest_dir: directory where a file will be extracted
    :return: Path obj to file
    :raises: ValueError
    """
    with ZipFile(path_to_zip) as zip_file:
        for name in zip_file.namelist():
            if filename_part in name:
                path = Path(zip_file.extract(name, dest_dir))
                return path
    raise ValueError("The zip file does not contain the file with '{}' in name!".format(filename_part))


def extract_all_files_from_zip(path_to_zip, dest_dir=None):
    """
    Search for specific file in zip and extract it to the given directory.
    :param path_to_zip: path to a zip file
    :param dest_dir: directory where a file will be extracted
    :return: list of Path objects
    """
    paths = []
    with ZipFile(path_to_zip) as zip_file:
        for name in zip_file.namelist():
            path = Path(zip_file.extract(name, dest_dir))
            paths.append(path)
        return paths


def extract_gz_file_content(gz_file_path, dest_dir=None):
    """
    Unpack gz file to the same or a new directory.
    :param gz_file_path: path to gz file
    :param dest_dir: a new directory where the gz file will be unpacked; default None
    :return: Path to unpacked file
    """
    directory = dest_dir if dest_dir is not None else gz_file_path.cwd()
    unpacked_file_path = Path(directory, gz_file_path.stem)
    with gzip.open(gz_file_path, 'rb') as gz_file:
        with open(unpacked_file_path, 'wb') as unpacked_file:
            shutil.copyfileobj(gz_file, unpacked_file)
    return unpacked_file_path
